
// !!!! PENDENT FORMAT
// !!!! PENDENT REVISAR DIFERENTS EXPLORADORS



//Dimensions de pàgina i marges
var PageW = 210
var PageH = 297
var marginE = 16
var marginD = 16
var marginT = 25
var marginB = 15
var maxWidthText = PageW - marginE - marginD

var paddingParam = 5

// Amplada de les columnes de la taula
var wCol1 = 27
var wCol2 = 29
var wCol3 = 33
var wCol4 = 17
var wCol5 = 13
var wCol6 = 12
var wCol7 = 23
var wCol8 = 26
//var wCol = [wCol1, wCol2, wCol3, wCol4, wCol5, wCol6, wCol7, wCol8]
var wCol
var hCelaTitol = 16
var hCelaText = 4

var hTextTitol = 5
var hParametres = 4
// Tamany de la lletra
var titol_size = 9
var parametres_size = 8
var titol_taula_size = 8
var text_size = 6
var num_pag = 1

var factor_conversio = (72/25.6)

var textcel = ''
var maxlinees = 0

var alerta_dades = false;

//al convertir les imatges a base 64, han d'estar en jpg (png no funciona)
var imgLogoCatSalut = 'data:image/jpeg;base64,'
var imgLogoGene ='data:image/jpeg;base64,'

function descarregarPDF(){		
	var doc = new jsPDF() // (orientation (p), unit (mm), format (a4), compressPdf (false) )
	var posY = marginT + hTextTitol	 // posició del cursor
	num_pag = 1
	
	//alerta de dades pendents de revisió (només mostrar si hi ha centres amb *)
	alerta_dades = ( $("#resultats #alerta_dades").length != 0);
	alerta_dades ? marginB = marginB + hParametres : marginB = marginB ;

	// --- capçalera del document ---
	posY = pintaCapcalera(doc, posY)
	posY = pintaTitolPagina(doc,posY)
	posY = posY + hParametres
	
	pintaPeuPagina(doc)

	// --- Paràmetres de cerca escollits --- 	
	posY = pintaParametres(doc, posY) 
	posY = posY + hParametres
	
	setAmplesColumnes();

	// --- Taula Capçaleres ---
	posY = pintaCapcaleraTaula(doc, posY);
	// --- pinta taula
	posY = pintaTaula(doc, posY);

	// --- guardar
	doc.save('llistesespera.pdf')
}

/* pinta el logo i el títol del document, retorna la posició del cursor*/
var pintaCapcalera = function(doc, posY){
	// --- Logo ---
	//doc.addImage(imgLogoCatSalut, 'JPEG', 6, 5, 88, 9);  // 362x37mm imatge salut	
	var ampleImgCatsalut = 52.45
	var altImgCatsalut = 9.75
	var ampleImgGene = 35.45
	var altImgGene = 9.75
	
	doc.addImage(imgLogoCatSalut,'JPEG', 15.9, 9.1, ampleImgCatsalut,altImgCatsalut);	
	doc.addImage(imgLogoGene,'JPEG', PageW-15.7-ampleImgGene, 8.7, ampleImgGene, altImgGene);

	posY = posY + hTextTitol * 2	
	
	return posY
}
var pintaTitolPagina = function(doc, posY){

	// --- Titol ---	
	var textTitol = "RESULTATS LLISTES D'ESPERA " + textResultats; 
	var text = doc.splitTextToSize(textTitol.toUpperCase(), maxWidthText*2)
	var altQuadre = hTextTitol * text.length 
		
	//enquadrat
	doc.setFontType("bold").setFontSize(titol_size) 
	doc.setFillColor(221, 221, 221) // Color per omplir zones #666666 
	doc.rect(marginE, posY - altQuadre, maxWidthText, altQuadre, 'FD')  // #666666 filled square with #ddd borders
	doc.text(marginE + 2, posY - 1, text)
	
	posY = posY + altQuadre
	return posY
}
var pintaPeuPagina = function(doc){
	doc.setFontType("normal").setFontSize(parametres_size)

	if (alerta_dades){
		var textAlerta = $("#alerta_dades").text();
		doc.text(marginE, PageH-hParametres-marginB/2, textAlerta);
	}

	var textData = "Llistes d'espera " + textResultats + ". CatSalut. Dades informatives en data: " 
	var d = new Date()
	textData = textData + d.getDate() + "/" + (d.getMonth() + 1) + "/" + d.getFullYear()
	doc.text(marginE, PageH-marginB/2, textData)

	// --- afegir peu de pàgina ---
	var textPagina = "Pàgina " + num_pag;
	var ampleText = doc.getStringUnitWidth(textPagina)*parametres_size/factor_conversio
	doc.text(PageW-marginD-ampleText, PageH-marginB/2, "Pàgina " + num_pag);
}

var pintaParametres = function(doc, posY){
	var textParam, text = "";
	var ampleText;

	/*GRUP D'INTERVENCIO*/
	if ($("#cercador").hasClass("quirurgiques")){
		text = "Grup d'intervenció: ";
		textParam = $(".caixaSelected").text().trim();
		posY = pintaParametre(doc, posY, text, textParam);
	}
	
	/*TIPUS D'INTERVENCIO*/
	text = textTaulaTipus + ": ";
	textParam = $('#p_tipus option:selected').text();
	posY = pintaParametre(doc, posY, text, textParam);
	
	/*MES*/
	text = "Mes: ";
	textParam = $('#p_mes option:selected').text();
	posY = pintaParametre(doc, posY, text, textParam);


	/*REGIO SANITARIA*/
	text = "Regió Sanitària: ";
	textParam = $('#p_rs option:selected').text();
	posY = pintaParametre(doc, posY, text, textParam);


	/*CENTRE SANITARI*/
	text = "Centre sanitari: ";
	textParam = $('#p_centre option:selected').text();
	posY = pintaParametre(doc, posY, text, textParam);
	
	return posY;
}
var pintaParametre = function(doc, posY, text1, text2){
	doc.setFontType("bold").setFontSize(parametres_size)
	ampleText = doc.getStringUnitWidth(text1)*parametres_size/factor_conversio
	doc.text(marginE + paddingParam, posY, text1)
	doc.setFontType("normal").text(marginE + paddingParam + ampleText, posY, text2);
	posY = posY + hParametres
	return posY
}

var afegirPagina = function(doc, posY){	
	// --- afegir pàgina ---
	doc.addPage();
	num_pag = num_pag + 1;
	posY = marginT;
		
	pintaPeuPagina(doc)
	// --- Logo ---
	//doc.addImage(imgLogoCatSalut, 'JPEG', 5, 5, 97, 10);	
	
	// --- Capcalera taula ---
	posY = pintaCapcaleraTaula(doc, posY);

	return posY
}

var setAmplesColumnes = function(){
	var ampleTaula = parseInt($("#taulaResultats").css("width").replace("px",""));
	var ampleCol = parseInt($(".titol1").css("width").replace("px",""));
	wCol1 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = parseInt($(".titol2").css("width").replace("px",""));
	wCol2 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = parseInt($(".titol3").css("width").replace("px",""));
	wCol3 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = ($(".titol4").css('display') != 'none') ? parseInt($(".titol4").css("width").replace("px","")) : 0;
	wCol4 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = ($(".titol5").css('display') != 'none') ? parseInt($(".titol5").css("width").replace("px","")) : 0;
	wCol5 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = ($(".titol6").css('display') != 'none') ? parseInt($(".titol6").css("width").replace("px","")) : 0;
	wCol6 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = ($(".titol7").css('display') != 'none') ? parseInt($(".titol7").css("width").replace("px","")) : 0;
	wCol7 = ampleCol * maxWidthText / ampleTaula; 
	ampleCol = ($(".titol8").css('display') != 'none') ? parseInt($(".titol8").css("width").replace("px","")) : 0;
	wCol8 = ampleCol * maxWidthText / ampleTaula; 

	wCol = [wCol1, wCol2, wCol3, wCol4, wCol5, wCol6, wCol7, wCol8]; 
}

/* Pinta les capçaleres de la taula
   retorna la nova posició del cursor */
var pintaCapcaleraTaula = function(doc, posY){
	var x = marginE	
	
	doc.setFontSize(titol_taula_size)// Tamany de la lletra
	doc.setFontType("bold") 
	doc.setFillColor(221, 221, 221)  // Color per omplir zones #666666 (102, 102, 102)
		
	hCelaTitolRect = hCelaTitol;
	if ($("#cercador").hasClass("externes")){
		hCelaTitolRect = hCelaTitol + hCelaText;
	} 
	
	//pintem cel·les i texts
	doc.rect(x, posY, wCol1, hCelaTitolRect, 'FD')  // #666666 filled square with #ddd borders
	doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize(textTaulaTipus.toUpperCase(), wCol1 -2))
	x = x + wCol1
	
	//doc.setTextColor(255, 255, 255)  // Color de la lletra
	doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	doc.rect(x, posY, wCol2, hCelaTitolRect, 'FD') 
	doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize($("#taulaUnicaResultats .titol2").html().toUpperCase(), wCol2 -2))
	x = x + wCol2
	
	//doc.setTextColor(255, 255, 255)  // Color de la lletra
	doc.setFillColor(221, 221, 221)  // Color per omplir zones 
    doc.rect(x, posY, wCol3, hCelaTitolRect, 'FD')  
	doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize($("#taulaUnicaResultats .titol3").html().toUpperCase(), wCol3 -2))
	x = x + wCol3
	
	
	if( $("#taulaUnicaResultats .titol4").css('display') != 'none' ) {
		doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	    doc.rect(x, posY, wCol4, hCelaTitolRect, 'FD') 
		doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize($("#taulaUnicaResultats .titol4").html().toUpperCase(), wCol4 -2))
		x = x + wCol4
	}
	
	if( $("#taulaUnicaResultats .titol5").css('display') != 'none' ) { 
		doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	    doc.rect(x, posY, wCol5, hCelaTitolRect, 'FD') 
		doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize($("#taulaUnicaResultats .titol5").html().toUpperCase(), wCol5 -2))
		x = x + wCol5
	}
	if( $("#taulaUnicaResultats .titol6").css('display') != 'none' ) {
		doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	    doc.rect(x, posY, wCol6, hCelaTitolRect, 'FD') 
		doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize($("#taulaUnicaResultats .titol6").html().toUpperCase(), wCol6 -2))
		x = x + wCol6
	}

	if( $("#taulaUnicaResultats .titol7").css('display') != 'none' ) {
		doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	    doc.rect(x, posY, wCol7, hCelaTitolRect, 'FD') 
		doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize(textSeccioIntervinguts.toUpperCase(), wCol7 -2))
		x = x + wCol7
	}

	if( $("#taulaUnicaResultats .titol8").css('display') != 'none' ) {
		doc.setFillColor(221, 221, 221)  // Color per omplir zones 
	    doc.rect(x, posY, wCol8, hCelaTitolRect, 'FD') 
		doc.text(x +1, posY + hCelaTitol - 12, doc.splitTextToSize(textSeccioEspera.toUpperCase(), wCol8 -2))	
		x = x + wCol8
	}

	posY = posY + hCelaTitolRect
	return posY
}

var pintaTaula = function(doc, posY){ 
    var oTable = document.getElementById('taulaUnicaResultats');

    var rowLength = oTable.rows.length;
	var x = marginE
    //loops through rows    
	for (i = 0; i < rowLength; i++){ 
		id = (oTable.rows.item(i)).id


		if(id.indexOf("fila") > -1){
			//gets cells of current row  
			var oCells = oTable.rows.item(i).cells;

			//gets amount of cells of current row
			var cellLength = oCells.length;
			var texts = [];
            //loops through each cell in current row
            maxlinees = 0;
			for(var j = 0; j < cellLength; j++){

				var concret = oCells.item(j);
				if( $(concret).css('display') != 'none' ) {

					// get your cell info here
					var cellVal = oCells.item(j).innerHTML;
					if(typeof(cellVal) !== 'undefined'){
						texts[j] = cellVal;
						textcel = doc.splitTextToSize(cellVal, wCol[j] -1)
						if(maxlinees < textcel.length){
							maxlinees = textcel.length
						}
					}
				}
			}
			x = marginE
			var altCela = hCelaText * maxlinees
			if (posY >= (PageH - marginB - altCela)){  // cursor ha arribat al final de la pàgina imprimible
				posY = afegirPagina(doc, posY)
			}
			for(var n = 0; n < cellLength; n++){
				if(typeof(texts[n]) !== 'undefined'){ 
					doc.setFontType('normal')	
					textcel = doc.splitTextToSize(texts[n], wCol[n] -1)
					doc.text(x+1,posY+hCelaText-1,textcel);
					doc.rect(x, posY, wCol[n], altCela)
					x = x + wCol[n]
				}
			}
			posY = posY + altCela
		}
	}
	return posY;
}


/* funcions de debug */

var drawMargins = function(doc){
	doc.setDrawColor(0, 0, 255)
	.setLineWidth(1/72)
	.line(marginE, 0, marginE, PageH)  // x, y, x2, y2 // marge esquerre
	.line(PageW - marginE, 0, PageW-marginE, PageH)    // marge dret
	.line(0, marginT, PageW, marginT)    // marge superior
	.line(0, PageH-marginB, PageW, PageH-marginB)    // marge inferior

	doc.setDrawColor(255, 0, 0)
	.setLineWidth(1/72)
	.line(1, 0, 1, PageH)  // x, y, x2, y2 // esq
	.line(PageW - 1, 0, PageW-1, PageH)    // dret
	.line(0, 1, PageW, 1)    // superior
	.line(0, PageH-1, PageW, PageH-1)    // inferior
	return doc
}
var drawPosY = function(doc, t){
	doc.setDrawColor(0, 0, 255)
	.setLineWidth(1/72)
	.line(marginE-5, posY, marginE, posY)  // x, y, x2, y2
	doc.text(marginE-5, posY, t)
	return doc
}

var drawContorn = function(doc, x, y, w, h){
	doc.setDrawColor(0, 0, 255)
	.setLineWidth(1/72)
	.line(x, y, x, y+h)  // x, y, x2, y2 // marge esquerre
	.line(x+w, y, x+w, y+h)    // marge dret
	.line(x, y, x+w, y)    // marge superior
	.line(x, y+h, x+w, y+h)    // marge inferior
	doc.setDrawColor(0, 0, 0)
}
